-- chair-step: inverse of read_lane_v2_b2_20_agent_cmp_comparison_entries — un-enrolls agent.cmp_comparison_entries from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'agent' and table_name = 'cmp_comparison_entries' and is_active);
select iam.apply_rls('agent', 'cmp_comparison_entries', (select token from platform.entity_types where schema_name = 'agent' and table_name = 'cmp_comparison_entries' and is_active), (select rls_variant from platform.entity_types where schema_name = 'agent' and table_name = 'cmp_comparison_entries' and is_active));
